		wantErr  bool
	}{
		{in: "3600", expected: time.Hour},
		{in: "1h30m", expected: 90 * time.Minute},
		{in: "0", expected: 0},
		{in: "-5", wantErr: true},
		{in: "-1s", wantErr: true},
		{in: "abc", wantErr: true},
	}
	for _, tt := range tests {
		t.Run(tt.in, func(t *testing.T) {
			d, err := parseCookieTTL(tt.in)
			if tt.wantErr {
				assert.Error(t, err)
				return
			}
			require.NoError(t, err)
			assert.Equal(t, tt.expected, d)
		})
	}
}

